const $$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const state={data:{settings:{},services:[],portfolio:[],jobs:[]},user:null,csrf:'',unread:0,admin:null,portal:null,serviceFilter:'All',portfolioFilter:'All',adminTab:'overview',portalTab:'requests',prefService:'',testimonialTimer:null,testimonialAdminCount:0,clientLogoAdminCount:0,siteContentDraft:null,ready:false};
