const MAX_PROJECT_GALLERY_IMAGES=8;
const MAX_PROJECT_IMAGE_LENGTH=200000;

const THEME_KEY='acphix-theme';
function getStoredTheme(){try{let t=localStorage.getItem(THEME_KEY);return t==='light'?'light':'dark'}catch(_){return 'dark'}}
function applyTheme(theme){document.body.classList.toggle('light-theme',theme==='light');document.body.dataset.theme=theme;const btn=$('#theme-switch');if(btn){const label=theme==='light'?'Switch to dark mode':'Switch to light mode';btn.setAttribute('aria-label',label);btn.setAttribute('title',label);btn.setAttribute('aria-pressed',String(theme==='light'));}}
function initTheme(){applyTheme(getStoredTheme());const btn=$('#theme-switch');if(btn&&!btn.dataset.bound){btn.dataset.bound='1';btn.addEventListener('click',()=>{const next=document.body.classList.contains('light-theme')?'dark':'light';try{localStorage.setItem(THEME_KEY,next)}catch(_){}applyTheme(next);});}}

