function icon(n,size=20){return `<svg viewBox="0 0 24 24" width="${size}" height="${size}" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.sparkles}</svg>`}
function h(v=''){return String(v??'').replace(/[&<>"']/g,s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s]));}
function money(v){return 'LKR '+new Intl.NumberFormat('en-LK',{maximumFractionDigits:0}).format(Number(v||0))}

function photoUrl(value){const src=String(value||'').trim();if(/^\/assets\/[a-zA-Z0-9._/-]+$/.test(src)&&!src.includes('..'))return src;if(/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src)&&src.length<=300000)return src;return safeUrl(src)}
function priceLabel(s){return s.price_visible!==0 && Number(s.starting_price)>0?`<small>From</small>${money(s.starting_price)}`:'Custom quote'}
const portfolioConceptImages={'nova-digital':'/assets/concept-digital-products.webp','form-and-feeling':'/assets/concept-brand-identity.webp','signal-in-motion':'/assets/concept-motion-studio.webp'};
function countMetric(name,value,description,ic,suffix='+'){const num=Number(value),valid=value!==''&&value!==null&&value!==undefined&&Number.isFinite(num)&&num>0;return `<article class="metric-card" tabindex="0" data-counter-card><div class="metric-icon">${icon(ic,22)}</div><div class="metric-value" ${valid?`data-count-to="${Math.floor(num)}" data-count-suffix="${h(suffix)}"`:''}>${valid?Math.floor(num).toLocaleString('en-LK')+suffix:'—'}</div><div class="metric-title">${h(name)}</div><p class="metric-description">${h(description)}</p></article>`}

function studioMetrics(){let s=state.data.settings;let regions=(s.client_regions||'').split(',').map(x=>x.trim()).filter(Boolean);let countries=s.stat_countries||String(regions.length||'');return `<section class="metrics-section" id="studio-impact"><div class="container"><div class="metric-grid glass-tile">${countMetric('Happy clients',s.stat_clients,'Clients served','users')}${countMetric('Projects completed',s.stat_projects,'Projects delivered','check')}${countMetric('Countries served',countries,'Global collaborations','external','')}${countMetric('Client satisfaction',s.stat_satisfaction,'Measured client feedback','sparkles','%')}</div><p class="metric-footnote">Figures are managed by Acphix. Unverified statistics are not shown.</p></div></section>`}

const mapCoordinates={'sri lanka':[579,205],'india':[563,174],'united arab emirates':[520,161],'uae':[520,161],'saudi arabia':[498,148],'singapore':[631,223],'malaysia':[624,215],'united kingdom':[395,79],'uk':[395,79],'france':[405,102],'germany':[422,87],'italy':[426,114],'united states':[178,117],'usa':[178,117],'canada':[164,74],'australia':[695,294],'new zealand':[769,331],'japan':[711,92],'south korea':[682,99],'china':[649,120],'qatar':[514,163],'maldives':[563,206],'thailand':[622,169]};
function reachMap(){let s=state.data.settings,regions=(s.client_regions||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,30);let points=regions.map(r=>({label:r,coord:mapCoordinates[r.toLowerCase()]})).filter(x=>x.coord&&x.label.toLowerCase()!=='sri lanka');let markers=points.map(p=>`<g class="map-client-pin" transform="translate(${p.coord[0]} ${p.coord[1]})" tabindex="0" aria-label="Client location: ${h(p.label)}"><title>${h(p.label)}</title><circle class="pin-wave" r="14" fill="#ffc200" opacity=".10"/><circle class="pin-core" r="5.2" fill="#ffc200" stroke="#ffd95f" stroke-width="1.4"/></g>`).join('');const count=Number(s.stat_countries||regions.length||0);const summary=count>0?`Based in Sri Lanka, working with brands in ${count} ${count===1?'country':'countries'}.`:'Based in Sri Lanka. Our global collaborations grow with every project.';return `<section class="section reach-section" id="global-reach"><div class="container reach-layout"><div class="reach-copy"><h2 class="section-heading">Clients around the<br/>world<span class="reach-period">.</span></h2><p>${summary}</p><div class="reach-tags">${regions.length?regions.map(r=>`<span>${h(r)}</span>`).join(''):`<span>📍 Sri Lanka · Studio HQ</span>`}</div><p class="reach-small">${regions.length?'Location markers represent regions verified by Acphix.':'Verified client locations can be added through your admin dashboard.'}</p></div><div class="map-glass glass-tile"><svg class="worldmap" viewBox="0 0 800 390" role="img" aria-label="Dotted world map; Sri Lanka is the Acphix studio headquarters. Other locations are displayed when verified in admin settings."><image href="/assets/world-dots.svg" width="800" height="390"/><g class="map-hq-pin" transform="translate(579 205)"><title>Acphix studio headquarters — Sri Lanka</title><circle class="pin-wave" r="17" fill="#ffc200" opacity=".11"/><circle class="pin-core" r="5.6" fill="#ffc200" stroke="#ffe07c" stroke-width="1.7"/></g>${markers}</svg><div class="map-note"><span class="map-live-dot"></span>Acphix Studio / Sri Lanka <span class="map-note-right">GLOBAL REACH</span></div></div></div></section>`}

function date(v){try{return new Intl.DateTimeFormat('en-LK',{day:'numeric',month:'short',year:'numeric'}).format(new Date(v))}catch{return v||''}}
function safeUrl(url){try{const u=new URL(url);return u.protocol==='https:'?u.href:''}catch{return ''}}
function field(label,name,value='',type='text',required=false,placeholder='',more=''){let rows=type==='textarea';return `<div class="field ${more}"><label for="f-${h(name)}">${h(label)}${required?' *':''}</label>${rows?`<textarea id="f-${h(name)}" name="${h(name)}" placeholder="${h(placeholder)}" ${required?'required':''}>${h(value)}</textarea>`:`<input id="f-${h(name)}" name="${h(name)}" type="${h(type)}" value="${h(value)}" placeholder="${h(placeholder)}" ${required?'required':''} ${type==='number'?'min="0"':''}/>`}</div>`}
function selectField(label,name,options,value='',required=false,more=''){return `<div class="field ${more}"><label for="f-${h(name)}">${h(label)}${required?' *':''}</label><select id="f-${h(name)}" name="${h(name)}" ${required?'required':''}><option value="">Select an option</option>${options.map(o=>`<option value="${h(o.value)}" ${String(o.value)===String(value)?'selected':''}>${h(o.label)}</option>`).join('')}</select></div>`}
function api(path,{method='GET',body}={}){let headers={'Accept':'application/json'};if(body!==undefined)headers['Content-Type']='application/json';if(state.csrf&&method!=='GET')headers['X-CSRF-Token']=state.csrf;return fetch(path,{method,headers,credentials:'same-origin',body:body===undefined?undefined:JSON.stringify(body)}).then(async r=>{let data=await r.json().catch(()=>({detail:'Unable to read server response',error:'Unable to read server response'}));if(!r.ok)throw new Error(data.detail||data.error||`Request failed (${r.status})`);return data})}
function toast(message,error=false){const e=document.createElement('div');e.className='toast'+(error?' error':'');e.textContent=message;$('#toast-region').append(e);setTimeout(()=>e.remove(),4200)}
function setupSettingsUploads(){$$('[data-testimonial-image],[data-client-logo-image]').forEach(input=>{input.addEventListener('change',()=>{const file=input.files?.[0];if(!file)return;if(!/^image\/(jpeg|png|webp)$/.test(file.type)){toast('Choose a JPG, PNG or WebP image.',true);input.value='';return}if(file.size>MAX_UPLOAD_FILE_SIZE){toast('Choose an image up to 10 MB.',true);input.value='';return}const isLogo=input.hasAttribute('data-client-logo-image'),targetId=input.dataset.testimonialImage||input.dataset.clientLogoImage;const reader=new FileReader();reader.onload=()=>{const image=new Image();image.onload=()=>{const size=isLogo?480:320,scale=Math.min(1,size/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.round(image.width*scale);canvas.height=Math.round(image.height*scale);const context=canvas.getContext('2d');if(!context){toast('The selected image could not be processed.',true);return}context.drawImage(image,0,0,canvas.width,canvas.height);let data=isLogo?canvas.toDataURL('image/webp',.78):canvas.toDataURL('image/jpeg',.82);if(isLogo&&data.length>45000)data=canvas.toDataURL('image/webp',.55);if(isLogo&&data.length>45000){toast('This logo is too large to save. Choose a smaller image.',true);input.value='';return}const target=$('#'+CSS.escape(targetId));if(target){target.value=data;target.dispatchEvent(new Event('input',{bubbles:true}))}toast(isLogo?'Client logo ready to save.':'Testimonial image ready to save.')};image.onerror=()=>toast('The selected image could not be read.',true);image.src=String(reader.result||'')};reader.readAsDataURL(file)})})}
async function bootstrap(){try{const [data,session]=await Promise.all([fetch('/api/bootstrap').then(async r=>{if(!r.ok)throw new Error('Static fallback');return r.json()}).catch(async()=>{const r=await fetch('/bootstrap.json',{cache:'no-store'});if(!r.ok)throw new Error('Unable to load website content');return r.json()}),fetch('/api/session').then(async r=>r.ok?r.json():{user:null,csrf:'',unread:0}).catch(()=>({user:null,csrf:'',unread:0}))]);state.data=data;state.user=session.user||null;state.csrf=session.csrf||'';state.unread=session.unread||0;state.ready=true;render()}catch(e){state.ready=true;$('#app').innerHTML=`<section class="login-layout"><div class="auth-box"><h1>Connection unavailable</h1><p>${h(e.message)}</p><a class="btn-dark" href="/">Try again ${icon('arrow-up-right')}</a></div></section>`}}
async function refreshSession(){let s=await api('/api/session');state.user=s.user||null;state.csrf=s.csrf||'';state.unread=s.unread||0;return s}
async function refreshAll(){state.data=await api('/api/bootstrap');await refreshSession();if(route().section==='admin')state.admin=await api('/api/admin');if(route().section==='portal')state.portal=await api('/api/portal');render()}
function route(){let raw=(location.hash||'#/').slice(1),[path,query='']=raw.split('?');let parts=path.split('/').filter(Boolean);return{section:parts[0]||'home',slug:parts[1]||'',query:new URLSearchParams(query)}}
function footer(){let s=state.data.settings;let socials=[['facebook','f','Facebook'],['instagram','ig','Instagram'],['tiktok','♪','TikTok'],['behance','Bē','Behance']].map(([k,g,label])=>{let u=safeUrl(s[k]);return u?`<a class="social-icon" href="${h(u)}" target="_blank" rel="noopener noreferrer" title="${label}" aria-label="${label}">${g}</a>`:`<span class="social-icon disabled" title="Add ${label} link in admin settings" aria-label="${label} link not configured">${g}</span>`}).join('');return `<div class="footer-grid"><div class="footer-brand"><a href="#/"><img class="footer-logo" src="/assets/acphix-white.png" alt="Acphix"/></a><p class="footer-tagline">Designing Innovation,<br/>Empowering Technology.</p><div class="footer-socials">${socials}</div></div><div class="footer-col"><h4>Explore</h4><a href="#/">Home</a><a href="#/about">About us</a><a href="#/portfolio">Selected work</a><a href="#/careers">Careers</a></div><div class="footer-col"><h4>Expertise</h4><a href="#/services">Web & software</a><a href="#/services">Design & branding</a><a href="#/services">Marketing & content</a><a href="#/services">AI automation</a></div><div class="footer-col"><h4>Let's connect</h4><a href="#/contact">Start a project ↗</a>${s.contact_email?`<a href="mailto:${h(s.contact_email)}">${h(s.contact_email)}</a>`:''}${s.phone?`<a href="tel:${h(s.phone.replace(/[^0-9+]/g,''))}">${h(s.phone)}</a>`:''}${s.phone_secondary?`<a href="tel:${h(s.phone_secondary.replace(/[^0-9+]/g,''))}">${h(s.phone_secondary)}</a>`:''}<span>${h(s.location||'Sri Lanka')}</span></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} <b>Acphix.</b> Crafted with purpose in Sri Lanka.</span><span>Creativity × Strategy × Technology</span></div>`}
function updateHeader(){let r=route(),admin=state.user?.role==='admin';$('#header').classList.toggle('solid',['login','register','admin','portal'].includes(r.section));$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===(r.section==='home'?'home':r.section)));$('#announcement-text').textContent=state.data.settings.announcement||'';const acc=$('#account-link');acc.textContent=state.user?(admin?'Dashboard':'My portal'):'Login';acc.href=state.user?(admin?'#/admin':'#/portal'):'#/login';$('#bell').hidden=!state.user;$('#unread-count').hidden=!state.user||!state.unread;$('#unread-count').textContent=state.unread>99?'99+':String(state.unread)}
function render(){if(!state.ready)return;if(state.testimonialTimer){clearInterval(state.testimonialTimer);state.testimonialTimer=null}let r=route();document.body.dataset.page=r.section;document.title=({home:'Acphix — Creative × Technology Studio',about:'About Acphix',services:'Our Services — Acphix',portfolio:'Portfolio — Acphix',careers:'Careers — Acphix',contact:'Contact Acphix',login:'Sign in — Acphix',register:'Join Acphix',portal:'Client Portal — Acphix',admin:'Admin Studio — Acphix'}[r.section]||'Acphix')+' | Designing Innovation';updateHeader();$('#footer').innerHTML=footer();const app=$('#app');const sections={home:homePage,about:aboutPage,services:servicesPage,portfolio:portfolioPage,careers:careersPage,contact:contactPage,login:loginPage,register:registerPage,portal:portalPage,admin:adminPage};app.innerHTML=(sections[r.section]||notFound)();if(r.section==='home'&&$('#global-reach',app))$('#global-reach',app).insertAdjacentHTML('afterend',clientLogosSection());setupMotion();setupSettingsUploads();setupTestimonialCarousels();setupClientLogoRails();if(r.section==='admin'&&state.user?.role==='admin'&&!state.admin)loadAdmin();if(r.section==='portal'&&state.user&&!state.portal)loadPortal();const menu=$('#mobile-menu');menu.hidden=true;$('#mobile-toggle').setAttribute('aria-expanded','false');$('#header').classList.toggle('stuck',scrollY>30)}
function notFound(){return pageHero('404 / Page not found','This page is still exploring the future.','Find your way back to Acphix.')+`<section class="section"><div class="container"><a class="btn-dark" href="#/">Back to home ↗</a></div></section>`}
function pageHero(title,subtitle,eyebrow='ACPHIX / EXPLORE'){return `<section class="page-hero"><div class="page-hero-inner"><div class="eyebrow gold">${h(eyebrow)}</div><h1>${title}</h1><p>${h(subtitle)}</p><span class="page-code">A / ${h(route().section.toUpperCase())} — 2026</span></div></section>`}
function head(kicker,title,intro='',link='',label='Explore more'){return `<div class="section-head"><div><div class="eyebrow">${h(kicker)}</div><h2 class="section-heading">${title}</h2></div>${intro?`<p class="section-intro">${h(intro)}</p>`:link?`<a href="${link}" class="text-link">${h(label)} <span>↗</span></a>`:''}</div>`}
function serviceCard(s,index=0,featured=false){return `<a class="service-card reveal ${featured?'featured':''}" href="#/services?focus=${h(s.slug)}"><div class="service-icon">${icon(s.icon)}</div><h3>${h(s.name)}</h3><p>${h(s.summary)}</p><div class="card-bottom"><span class="card-category">${h(s.category)}</span><span class="round-arrow">↗</span></div></a>`}
function artGlyph(p){return p.visual==='electric'?'N/':p.visual==='rose'?'F°':p.visual==='amber'?'S/':(p.title||'A').split(' ').map(w=>w[0]).slice(0,2).join('')}
function workImage(p,i){let image=photoUrl(p.image_url)||portfolioConceptImages[p.slug]||'';return `<div class="work-image ${h(p.visual)} ${image?'with-photo':''}">${image?`<img src="${h(image)}" alt="${h(p.title)} ${p.project_type==='concept'?'creative concept artwork':'project cover'}" loading="eager" decoding="async"/>`:`<div class="art-circle"></div><div class="art-glyph">${h(artGlyph(p))}</div>`}<span class="work-corner">${p.project_type==='concept'?'Concept project':'Client project'}</span><span class="work-index">0${i+1} / ACPHIX</span><span class="work-hover-action">Explore case study ↗</span></div>`} 
function workCard(p,i,layout=''){return `<a class="work-card reveal ${h(layout)}" href="#/portfolio/${encodeURIComponent(p.slug)}">${workImage(p,i)}<span class="work-category">${h(p.category)}</span><h3>${h(p.title)} ↗</h3><p>${h(p.summary)}</p></a>`}
function homeWorkCard(p,i){let image=photoUrl(p.image_url)||portfolioConceptImages[p.slug]||'',mark=photoUrl(p.mark_url)||'',layout=i===0?'home-bento-feature':i<3?'home-bento-side':'home-bento-bottom';return `<a class="home-work-card reveal ${layout}" href="#/portfolio/${encodeURIComponent(p.slug)}" aria-label="View case study: ${h(p.title)}">${image?`<img class="home-work-cover" src="${h(image)}" alt="" loading="${i<3?'eager':'lazy'}" decoding="async"/>`:`<div class="home-work-placeholder ${h(p.visual)}"><span>${h(artGlyph(p))}</span></div>`}${mark?`<img class="home-work-mark" src="${h(mark)}" alt="" loading="lazy"/>`:''}<div class="home-work-overlay"><span class="home-work-category">${h(p.category)}</span><h3>${h(p.title)}</h3><p>${h(p.summary)}</p><span class="home-work-action">View Case Study ↗</span></div></a>`}
function portfolioTileSpans(count){let spans=[];for(let i=0;i<count;i+=5){let group=Math.min(5,count-i);if(group===5)spans.push('tile-wide','tile-narrow','tile-third','tile-third','tile-third');else if(group===4)spans.push('tile-wide','tile-narrow','tile-half','tile-half');else if(group===3)spans.push('tile-third','tile-third','tile-third');else if(group===2)spans.push('tile-wide','tile-narrow');else spans.push('tile-full')}return spans}
function steps(){return `<section class="section steps-section"><div class="container">${head('Our way of working','Good ideas deserve<br/>great execution.','One collaborative process. No unnecessary complications. Just the right minds connecting the dots.')}<div class="steps-grid">${[['01','Discover','We listen, research and get to the heart of what matters.'],['02','Define','A considered plan shapes the right creative and technical direction.'],['03','Create','Design, content and engineering move together, not in silos.'],['04','Evolve','We refine, launch, learn and build for what comes next.']].map(([num,t,desc])=>`<article class="step-card reveal"><span class="step-no">/ ${num}</span><span class="step-line"></span><h3>${t}</h3><p>${desc}</p></article>`).join('')}</div></div></section>`}
